// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNum, uint160 senderSeed, uint256 timeSeed) public {
        // bound inputs to avoid overflow in block.timestamp arithmetic
        uint256 warpTime = bound(timeSeed, 1, type(uint256).max - 1);
        address sender = address(uint160(bound(senderSeed, 1, type(uint160).max)));

        // warp to a block number where % 15 != 0 so the transfer does NOT happen
        vm.assume(blockNum % 15 != 0);
        vm.warp(warpTime);

        // record balance before
        uint256 balBefore = address(c).balance;

        // fund sender with 10 ether
        vm.deal(sender, 10 ether);
        vm.prank(sender);
        (bool success, ) = address(c).call{value: 10 ether}("");

        require(success, "fallback should succeed");

        // check that balance increased by exactly 10 ether (no transfer happened)
        assertTrue(address(c).balance == balBefore + 10 ether);
    }
}

